/* Changing PascalCasing to camelCasing in platform responses, eg.

   Input:
    {
        "ShowTopBlog": true,
        "TopBlogText": "Invia il tuo documento di identità",
        "TopBlogColor": "#00b2ac",
        "TopBlogBackGroundColor": "#fbed66",
        ...
    }

    Output:
    {
        "showTopBlog": true,
        "topBlogText": "Invia il tuo documento di identità",
        "topBlogColor": "#00b2ac",
        "topBlogBackGroundColor": "#fbed66",
        ...
    }
*/

function camelCaseKey(key: string): string {
    return key.replace(key.substring(0, 1), (n: string) => n.toLowerCase());
}

/**
 * This function doesn't validate the response and should be used alongside validation such as the map-and-validate function
 */

export function camelCaseResponseConverter<T extends string | object>(response: T): any {
    const newResponse = JSON.parse(JSON.stringify(response));
    for (const key of Object.keys(newResponse)) {
        const newKey = camelCaseKey(key);

        if (typeof newResponse[key] === 'object' && newResponse[key] !== null) {
            newResponse[key] = camelCaseResponseConverter(newResponse[key]);
        }

        // Key is already camelCase
        if (newKey === key) {
            continue;
        }

        Object.defineProperty(newResponse, newKey, Object.getOwnPropertyDescriptor(newResponse, key)!);
        delete newResponse[key];
    }

    return newResponse;
}

